package com.bank.term.service;

import java.util.logging.Logger;

// Maximizes total interest by splitting a term into reusable sub-terms (unbounded).
public class TermSplitService {
    private static final Logger log = Logger.getLogger(TermSplitService.class.getName());

    // prices[len] = interest for a sub-term of length len (prices[0] unused = 0).
    public int maxRevenue(int[] prices, int length) {
        int[] dp = new int[length + 1];
        for (int len = 1; len < prices.length; len++) {
            // Upward sweep so the same sub-term length can repeat.
            for (int c = len; c <= length; c++) {
                dp[c] = Math.max(dp[c], prices[len] + dp[c - len]);
            }
        }
        log.info(() -> "Max interest for term " + length + " = " + dp[length]);
        return dp[length];
    }
}
