package com.bank.term;

import com.bank.term.service.TermSplitService;
import java.util.logging.Logger;

public class TermSplitApplication {
    private static final Logger log = Logger.getLogger(TermSplitApplication.class.getName());

    public static void main(String[] args) {
        TermSplitService service = new TermSplitService();
        // prices index 1..4: length 1→1, 2→5, 3→8, 4→9 (interest units)
        int[] prices = {0, 1, 5, 8, 9};
        int length = 4;
        int best = service.maxRevenue(prices, length);
        log.info("Best total interest for a term of length " + length + ": " + best);
    }
}
